update public.club_events set description = $about$A day-long Outdoor U workshop on native plants and how to use them in a home landscape. Participants tour the Saint John's herbarium, draw a plant, and turn the drawing into a linoleum block print to take home. It runs 10 a.m. to 4 p.m. and is capped at 15 people. The cost is $20 for Outdoor U members and CSB+SJU students and $30 for nonmembers; register through Outdoor U's online store.$about$ where id = '9267ef80-25d5-4816-ad9c-71896994da29';  -- Print making with native plants
update public.club_events set description = $about$Outdoor U's wreath workshop has each person build a handmade wreath from natural materials collected in the Saint John's Abbey Arboretum. No experience is needed. Each 90-minute session holds 20 people, and registration is through Outdoor U's online store. The cost is $20 for Outdoor U members, $25 for nonmembers and $10 for CSB+SJU students.$about$ where id = 'aaa92df3-a11f-464c-8d72-4a023f825301';  -- Wreath making at Outdoor U
update public.club_events set description = $about$Outdoor U's wreath workshop has each person build a handmade wreath from natural materials collected in the Saint John's Abbey Arboretum. No experience is needed. Each 90-minute session holds 20 people, and registration is through Outdoor U's online store. The cost is $20 for Outdoor U members, $25 for nonmembers and $10 for CSB+SJU students.$about$ where id = '341c04cf-626e-4fc3-9f6b-56df22485a57';  -- Wreath making at Outdoor U
update public.club_events set description = $about$Outdoor U's wreath workshop has each person build a handmade wreath from natural materials collected in the Saint John's Abbey Arboretum. No experience is needed. Each 90-minute session holds 20 people, and registration is through Outdoor U's online store. The cost is $20 for Outdoor U members, $25 for nonmembers and $10 for CSB+SJU students.$about$ where id = '03c2b9c6-e4fe-4483-bec0-9abf10a81455';  -- Wreath making at Outdoor U
