update public.club_events set description = $about$Eden Valley-Watkins opens the MSHSL Section 3AA volleyball playoffs at home. The Eagles are the No. 2 seed in the North half of the bracket and host No. 7 seed Montevideo in a first-round match.$about$ where id = '392178cf-0d3a-4b99-b87b-f7b5027ab2a7';  -- Eden Valley-Watkins Volleyball vs Montevideo
update public.club_events set description = $about$Flour & Flower Bakery's release party for the book A Court of Splintered Harmony includes a guided Paint & Sip led by Tia Connelly, open to all skill levels. The Paint & Sip ticket covers the painting, entry for the evening, a drink and the grazing table. The night also has ACOTAR trivia and a photo booth for guests who dress as a favorite character or court. Tickets are non-refundable.$about$ where id = '07008394-54c2-44e9-8e8b-49af1a68c02f';  -- Paint & Sip: Court of Splintered Harmony
update public.club_events set description = $about$A two-day continuing education course from My Plumbing Training for plumbers, water conditioning installers, building officials and residential contractors. It's held at Goodin Company's St. Joseph branch, a plumbing and heating supplier, and runs into a second day on Dec. 4. Registration is required through myplumbingtraining.com.$about$ where id = 'aadf4121-f74c-4898-852c-a6a9234fa9d0';  -- My Plumbing Training
update public.club_events set description = $about$Holistic Flower Farm, a St. Joseph flower farm that makes arrangements for events and holidays, leads a hands-on workshop building a holiday porch pot. The $65 fee covers all supplies. Spots are limited to 30 and registration is required.$about$ where id = '27acd067-5ad0-4d9c-b58e-e6cdc27663f2';  -- Holiday Porch Pot Workshop
update public.club_events set description = $about$A holiday kickoff at JoeTown's shops on First Avenue, with seasonal drinks from Obbink Distilling. Tickets are limited.$about$ where id = 'f559093b-18bc-47e4-9ac7-1d564bc78f1f';  -- Twinkle & Toast
update public.club_events set description = $about$Fall picture retake day for students at Kennedy Community School.$about$ where id = '05c12039-eba9-43a6-8ec7-e697c345c77d';  -- Fall Picture Retakes
update public.club_events set description = $about$Kennedy Community School's Trunk or Treat is a Halloween party for kids and families, where children trick-or-treat in costume. It has drawn a big turnout in past years.$about$ where id = '439ae780-8cf7-43a8-8a9b-202cc1549a59';  -- Trunk or Treat at Kennedy
update public.club_events set description = $about$The St. Cloud Area School District 742 Board of Education, which oversees Kennedy Community School, holds its first-Wednesday board meeting and work session at the District Administration Office in Waite Park. Meetings are livestreamed on the district's YouTube channel, and the board welcomes community input before its in-person meetings.$about$ where id = '8e35f9c1-a6c2-42d9-8fff-34a5e9e575fb';  -- School Board Meeting and Work Session
update public.club_events set description = $about$Kennedy Community School's junior high students compete in a Knowledge Bowl meet.$about$ where id = '15a3652a-6252-4f0b-bd05-ad4c1673eb59';  -- JH Knowledge Bowl
update public.club_events set description = $about$The Ptanyétu Powwow is free and open to the public, with grand entries at 1 and 5 p.m., a hand drum contest, food trucks and vendors. It's held in Clemens Fieldhouse at the College of Saint Benedict's Haehn Campus Center, with St. Cloud Technical and Community College among its sponsors.$about$ where id = '941220e1-734b-48df-9a78-80b50432ea71';  -- Ptanyétu Powwow
update public.club_events set description = $about$Meeting of Kennedy Community School's parent-teacher organization.$about$ where id = '06b7f40b-20be-4aaa-804a-b701dfea86d0';  -- PTO Meeting at Kennedy
update public.club_events set description = $about$Kennedy Community School's 6th grade orchestra students share what they've been learning in an informance, a casual performance that mixes playing with explaining.$about$ where id = 'deb05d15-2810-438a-b118-486e038310e9';  -- 6th Grade Orchestra Informance
update public.club_events set description = $about$The St. Cloud Area School District 742 Board of Education, which oversees Kennedy Community School, holds its regular third-Wednesday meeting at the District Administration Office in Waite Park. Meetings are livestreamed on the district's YouTube channel, and the board welcomes community input before its in-person meetings.$about$ where id = '14541224-5138-48f4-afa0-6f821b9f48d3';  -- School Board Meeting
update public.club_events set description = $about$Kennedy Community School's 6th through 8th graders compete in a Knowledge Bowl meet hosted at Saint John's Prep in Collegeville.$about$ where id = 'fdd32f02-56af-4513-b9b5-7e9f15a35d90';  -- Prep Knowledge Bowl 6-8 Grades
update public.club_events set description = $about$Last day of the first trimester at Kennedy Community School. There's no school the next day, Nov. 25 (a half-day teacher workshop), or Nov. 26 and 27 for Thanksgiving break.$about$ where id = '5d1985b4-c765-4835-9e71-5c8e647f113c';  -- First Trimester Ends
