update public.club_events set description = $about$Kimball opens the MSHSL Section 5-2A football playoffs as the No. 2 seed against No. 7 Kerkhoven-Murdock-Sunburg, a rematch of an Oct. 2 regular-season game. The winner plays the Cathedral and Eden Valley-Watkins winner on Oct. 31.$about$ where id = 'a4a5ad4f-56b2-49eb-bfe8-5c12ac791943';  -- Kimball Football vs Kerkhoven-Murdock-Sunburg
update public.club_events set description = $about$Story Feast Collective's five-course, family-style harvest dinner at the Weisman Art Museum is cooked by Mateo and Erin Mackbee of St. Joseph's Krewe and Flour & Flower Bakery. Milk & Honey Ciders pours its dry ciders, and tickets include a cocktail reception, all drinks, gallery access and a goody bag.$about$ where id = 'be42f28c-0044-4e75-b860-37f23640e315';  -- Harvest Feast with Milk & Honey
update public.club_events set description = $about$Stitch & Sip is an evening for knitters, crocheters and embroiderers in the Milk & Honey Ciders taproom, hosted by Yellow Brick Knits. It's free: bring a project and stitch alongside others with a cider.$about$ where id = 'ecdd6fcd-5c1e-4495-89b5-424a1b01cd9e';  -- Stitch & Sip
update public.club_events set description = $about$Milk & Honey Ciders teams up with Rugged Wellness MN's mobile barrel sauna and Shanti Yoga Center for an evening of outdoor yoga, sauna and cold water. The $40 ticket covers yoga, one 30-minute sauna and cold-water session (guests sign up for one of four time slots) and a cider, with non-alcoholic options. Check-in starts at 6 p.m.$about$ where id = '01ff9005-1987-4dc1-8ab8-75e3ef89369a';  -- Sauna, Yoga, Ice Bath, Cider
